void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec2 sourus = (iMouse.xy - 0.5 * iResolution.xy) / iResolution.y;
    if (iMouse.z <= 0.0) {
        sourus = vec2(sin(iTime * 1.5) * 0.3, cos(iTime * 1.2) * 0.15);
    }

    vec2 pWarp = uv * 4.0 + vec2(iTime * 0.1);
    float valWarp = 0.0;
    float ampWarp = 0.5;
    for (int k = 0; k < 3; k++) {
        vec2 iW = floor(pWarp);
        vec2 fW = fract(pWarp);
        fW = fW * fW * (vec2(3.0) - vec2(2.0) * fW);

        vec2 pA = fract(iW * vec2(123.34, 456.21)); pA = pA + vec2(dot(pA, pA + vec2(45.32)));
        vec2 pB = fract((iW + vec2(1.0, 0.0)) * vec2(123.34, 456.21)); pB = pB + vec2(dot(pB, pB + vec2(45.32)));
        vec2 pC = fract((iW + vec2(0.0, 1.0)) * vec2(123.34, 456.21)); pC = pC + vec2(dot(pC, pC + vec2(45.32)));
        vec2 pD = fract((iW + vec2(1.0, 1.0)) * vec2(123.34, 456.21)); pD = pD + vec2(dot(pD, pD + vec2(45.32)));

        float nW = mix(mix(fract(pA.x * pA.y), fract(pB.x * pB.y), fW.x),
                       mix(fract(pC.x * pC.y), fract(pD.x * pD.y), fW.x), fW.y);
        valWarp += ampWarp * nW;
        pWarp *= 2.0;
        ampWarp *= 0.5;
    }

    vec2 uvDeforme = uv + vec2(0.0, valWarp * 0.005);

    vec2 pPeau = uv * 12.0;
    float bruitPeau = 0.0;
    float ampPeau = 0.5;
    for (int k = 0; k < 3; k++) {
        vec2 iP = floor(pPeau);
        vec2 fP = fract(pPeau);
        fP = fP * fP * (vec2(3.0) - vec2(2.0) * fP);

        vec2 pA = fract(iP * vec2(123.34, 456.21)); pA = pA + vec2(dot(pA, pA + vec2(45.32)));
        vec2 pB = fract((iP + vec2(1.0, 0.0)) * vec2(123.34, 456.21)); pB = pB + vec2(dot(pB, pB + vec2(45.32)));
        vec2 pC = fract((iP + vec2(0.0, 1.0)) * vec2(123.34, 456.21)); pC = pC + vec2(dot(pC, pC + vec2(45.32)));
        vec2 pD = fract((iP + vec2(1.0, 1.0)) * vec2(123.34, 456.21)); pD = pD + vec2(dot(pD, pD + vec2(45.32)));

        float nP = mix(mix(fract(pA.x * pA.y), fract(pB.x * pB.y), fP.x),
                       mix(fract(pC.x * pC.y), fract(pD.x * pD.y), fP.x), fP.y);
        bruitPeau += ampPeau * nP;
        pPeau *= 2.0;
        ampPeau *= 0.5;
    }

    vec3 couleurPeauBase = mix(vec3(0.92, 0.73, 0.62), vec3(0.96, 0.78, 0.68), vec3(bruitPeau));

    vec2 centre = uvDeforme;
    float vignettage = 1.0 - dot(centre, centre) * 0.6;
    vec3 couleur = couleurPeauBase * vec3(vignettage);

    float humeur = mod(iTime * 0.4, 3.0);
    float angleDoux = -0.15;
    float angleEnColere = 0.40;
    float angleJoyeux = -0.30;
    float yDoux = 0.28;
    float yEnColere = 0.23;
    float yJoyeux = 0.32;
    float courbureBoucheDouce = 1.8;
    float courbureBoucheEnColere = -2.2;
    float courbureBoucheJoyeuse = 3.5;
    float boucheYDouce = -0.28;
    float boucheYEnColere = -0.30;
    float boucheYJoyeuse = -0.25;

    float angleActuel = 0.0;
    float yActuel = 0.0;
    float courbureBoucheActuelle = 0.0;
    float boucheYActuel = 0.0;

    if (humeur < 1.0) {
        float t = smoothstep(0.0, 1.0, humeur);
        angleActuel = mix(angleDoux, angleEnColere, t);
        yActuel = mix(yDoux, yEnColere, t);
        courbureBoucheActuelle = mix(courbureBoucheDouce, courbureBoucheEnColere, t);
        boucheYActuel = mix(boucheYDouce, boucheYEnColere, t);
    } else if (humeur < 2.0) {
        float t = smoothstep(1.0, 2.0, humeur);
        angleActuel = mix(angleEnColere, angleJoyeux, t);
        yActuel = mix(yEnColere, yJoyeux, t);
        courbureBoucheActuelle = mix(courbureBoucheEnColere, courbureBoucheJoyeuse, t);
        boucheYActuel = mix(boucheYEnColere, boucheYJoyeuse, t);
    } else {
        float t = smoothstep(2.0, 3.0, humeur);
        angleActuel = mix(angleJoyeux, angleDoux, t);
        yActuel = mix(yJoyeux, yDoux, t);
        courbureBoucheActuelle = mix(courbureBoucheJoyeuse, courbureBoucheDouce, t);
        boucheYActuel = mix(boucheYJoyeuse, boucheYDouce, t);
    }

    float cycleClignement = mod(iTime * 3.0, 6.0);
    float clignement = 1.0;
    if (cycleClignement > 5.5) {
        float tempsClignement = (cycleClignement - 5.5) / 0.5;
        clignement = abs(sin(tempsClignement * 3.14159));
    }

    vec2 posNez = uvDeforme - vec2(0.0, -0.10);
    float arcNez = posNez.y + posNez.x * posNez.x * 4.0;
    float distNez = abs(arcNez) - 0.02;
    if (abs(posNez.x) < 0.08 && posNez.y < 0.02 && posNez.y > -0.06) {
        vec3 couleurOmbreNez = couleurPeauBase * vec3(0.70);
        couleur = mix(couleurOmbreNez, couleur, vec3(smoothstep(-0.01, 0.015, distNez)));
    }

    vec2 posReflet = posNez - vec2(-0.015, 0.01);
    float refletNez = length(posReflet) - 0.025;
    if (refletNez < 0.0) {
        vec3 couleurRefletNez = couleurPeauBase * vec3(1.25);
        couleur = mix(couleurRefletNez, couleur, vec3(smoothstep(-0.02, 0.01, refletNez)));
    }

    vec2 posNarines = posNez;
    posNarines.x = abs(posNarines.x) - 0.06;
    posNarines.y += 0.02;
    float distNarines = length(posNarines) - 0.02;
    if (distNarines < 0.0) {
        vec3 ombreNarines = couleurPeauBase * vec3(0.55);
        couleur = mix(ombreNarines, couleur, vec3(smoothstep(-0.015, 0.01, distNarines)));
    }

    vec2 posBouche = uvDeforme - vec2(0.0, boucheYActuel);
    float arcBouche = posBouche.y + posBouche.x * posBouche.x * courbureBoucheActuelle;
    vec2 limitesBouche = vec2(0.18, 0.025);
    float distHorizBouche = abs(posBouche.x) - limitesBouche.x;
    float distLigneBouche = length(vec2(max(distHorizBouche, 0.0), arcBouche)) - limitesBouche.y;

    if (distLigneBouche < 0.0) {
        vec3 couleurLevres = mix(vec3(0.3, 0.1, 0.12), vec3(0.45, 0.18, 0.2), vec3(0.5 + 0.5 * sin(posBouche.x * 20.0)));
        float speculaireLevres = smoothstep(0.0, 0.01, -distLigneBouche) * 0.3;
        couleur = mix(couleurLevres + vec3(speculaireLevres), couleur, vec3(smoothstep(-0.003, 0.001, distLigneBouche)));
    }

    float espacementYeux = 0.35;
    float rayonOeil = 0.22;

    vec2 dirVersSouris = sourus;
    float distVersSouris = length(dirVersSouris);
    float decalageMax = rayonOeil - 0.08;
    vec2 decalagePupille = vec2(0.0);
    if (distVersSouris > 0.0001) {
        decalagePupille = (dirVersSouris / vec2(distVersSouris)) * vec2(min(distVersSouris, decalageMax));
    }

    for (int i = -1; i <= 1; i += 2) {
        float cote = float(i);
        vec2 centreOeil = vec2(cote * espacementYeux, 0.0);
        vec2 p = uvDeforme - centreOeil;

        p.y /= mix(0.1, 1.0, clignement);

        float distBlancOeil = length(p) - rayonOeil;

        if (clignement > 0.05 && distBlancOeil < 0.0) {
            vec3 couleurOeil = vec3(0.97, 0.97, 0.99);

            vec2 posPupille = p - decalagePupille;
            float distIris = length(posPupille);
            float angleIris = atan(posPupille.y, posPupille.x);

            vec2 pIris = posPupille * 15.0;
            float bruitIris = 0.0;
            float ampIris = 0.5;
            for (int k = 0; k < 3; k++) {
                vec2 iI = floor(pIris);
                vec2 fI = fract(pIris);
                fI = fI * fI * (vec2(3.0) - vec2(2.0) * fI);

                vec2 pA = fract(iI * vec2(123.34, 456.21)); pA = pA + vec2(dot(pA, pA + vec2(45.32)));
                vec2 pB = fract((iI + vec2(1.0, 0.0)) * vec2(123.34, 456.21)); pB = pB + vec2(dot(pB, pB + vec2(45.32)));
                vec2 pC = fract((iI + vec2(0.0, 1.0)) * vec2(123.34, 456.21)); pC = pC + vec2(dot(pC, pC + vec2(45.32)));
                vec2 pD = fract((iI + vec2(1.0, 1.0)) * vec2(123.34, 456.21)); pD = pD + vec2(dot(pD, pD + vec2(45.32)));

                float nI = mix(mix(fract(pA.x * pA.y), fract(pB.x * pB.y), fI.x),
                               mix(fract(pC.x * pC.y), fract(pD.x * pD.y), fI.x), fI.y);
                bruitIris += ampIris * nI;
                pIris *= 2.0;
                ampIris *= 0.5;
            }

            float motifIris = sin(angleIris * 12.0 + bruitIris * 4.0);

            float distFrontiereIris = distIris - 0.09;
            float distPupille = distIris - 0.045;
            float distReflet1 = length(posPupille - vec2(0.03, 0.03)) - 0.02;
            float distReflet2 = length(posPupille - vec2(-0.02, -0.025)) - 0.01;

            if (distFrontiereIris < 0.0) {
                vec3 irisBase = mix(vec3(0.08, 0.35, 0.75), vec3(0.12, 0.55, 0.85), vec3(0.5 + 0.5 * motifIris));
                irisBase *= vec3(1.0 - distIris * 3.0);
                couleurOeil = irisBase;
            }
            if (distPupille < 0.0) couleurOeil = vec3(0.01);
            if (distReflet1 < 0.0) couleurOeil = vec3(1.0);
            if (distReflet2 < 0.0) couleurOeil = vec3(0.8, 0.9, 1.0);

            float ombreInterieure = smoothstep(0.0, 0.15, p.y + rayonOeil * 0.55);
            couleurOeil *= mix(vec3(0.65), vec3(1.0), vec3(ombreInterieure));

            couleur = mix(couleurOeil, couleur, vec3(smoothstep(-0.002, 0.002, distBlancOeil)));
        }

        vec2 posSourcil = uvDeforme - (centreOeil + vec2(0.0, yActuel));
        posSourcil.x *= cote;

        float a = angleActuel;
        mat2 rotation = mat2(cos(a), -sin(a), sin(a), cos(a));
        posSourcil = rotation * posSourcil;

        vec2 tailleSourcil = vec2(0.18, 0.035);
        posSourcil.y += posSourcil.x * posSourcil.x * 1.8;

        vec2 d = abs(posSourcil) - tailleSourcil;
        float distSourcil = length(max(d, vec2(0.0))) + min(max(d.x, d.y), 0.0) - 0.01;

        if (distSourcil < 0.0) {
            couleur = mix(vec3(0.12, 0.06, 0.04), couleur, vec3(smoothstep(-0.004, 0.001, distSourcil)));
        }
    }

    couleur = pow(couleur, vec3(0.4545));
    fragColor = vec4(couleur, 1.0);
}
